import{_ as t,o as _,a as d,b as r}from"./app.ejsEy6QV.js";const g=JSON.parse('{"title":"","description":"","frontmatter":{"breadcrumbs":[{"text":"Ascend C算子开发指南","link":"/guide/getting_started/ascend_c_overview_and_learning_path"},{"text":"编程指南","link":"/guide/programming_guide/document_structure"},{"text":"高级编程","link":"/guide/programming_guide/advanced_programming/advanced_programming"},{"text":"Aclnn算子工程化开发","link":"/guide/programming_guide/advanced_programming/aclnn_operator_development/overview"},{"text":"附录","link":"/guide/programming_guide/advanced_programming/aclnn_operator_development/appendix/appendix"},{"text":"aclnn工程化算子开发与核函数（Kernel）直调对比","link":"/guide/programming_guide/advanced_programming/aclnn_operator_development/appendix/kernel_direct_call_comparison"}]},"headers":[],"relativePath":"guide/programming_guide/advanced_programming/aclnn_operator_development/appendix/kernel_direct_call_comparison.md","filePath":"guide/programming_guide/advanced_programming/aclnn_operator_development/appendix/kernel_direct_call_comparison.md","lastUpdated":1789438830000}'),a={name:"guide/programming_guide/advanced_programming/aclnn_operator_development/appendix/kernel_direct_call_comparison.md"};function o(n,e,c,i,l,p){return _(),d("div",null,[...e[0]||(e[0]=[r('<div><article class="markdown-body"><h1>aclnn工程化算子开发与核函数（Kernel）直调对比</h1><p>本文介绍aclnn工程化算子开发与核函数（Kernel）直调两种开发方式的差异，供开发者选择开发方式及迁移算子时参考。</p><table><thead><tr><th>特性</th><th>核函数（Kernel）直调</th><th>aclnn工程化算子开发</th></tr></thead><tbody><tr><td>调用入口</td><td>使用<code>&lt;&lt;&lt;&gt;&gt;&gt;</code>作为算子的调用入口，自行指定核函数及执行配置。</td><td>通过生成的两段式aclnn接口调用算子：第一段获取workspace大小和executor，第二段传入workspace、executor和stream执行。详见<a href="../invocation/single_operator_api_call.html">单算子API调用</a>。</td></tr><tr><td>入参结构规范</td><td>核函数入口支持传入结构体参数，结构体需为POD类型。例如：<br><code>struct AddParams;</code><br><code>__global__ __vector__ void add_kernel(__gm__ float* x, __gm__ float* y, __gm__ float* z, AddParams params);</code></td><td>核函数入口不支持直接传入结构体对象（按值传参）。核函数入口按照算子原型中的输入、输出顺序传入地址，随后追加workspace和tiling地址。Tiling参数通过TilingData结构体组织，并通过tiling地址传递和解析。例如，AddCustom有两个输入x、y和一个输出z，其入口声明为：<br><code>extern &quot;C&quot; __global__ __aicore__ void add_custom(GM_ADDR x, GM_ADDR y, GM_ADDR z, GM_ADDR workspace, GM_ADDR tiling);</code><br>其中x、y为输入地址，z为输出地址，workspace为工作空间地址，tiling为Tiling数据地址。详见<a href="../design_and_implementation/kernel_operator_implementation.html">核函数（Kernel）侧算子实现</a>。</td></tr><tr><td>Kernel Type</td><td>通过<code>__vector__</code>、<code>__cube__</code>或<code>__mix__</code>函数执行空间限定符设置核函数类型。</td><td>核函数入口使用<code>__global__ __aicore__</code>修饰，通过<code>KERNEL_TASK_TYPE_DEFAULT</code>设置默认类型，或通过<code>KERNEL_TASK_TYPE</code>按TilingKey设置类型。Tiling模板编程场景通过<code>ASCENDC_TPL_KERNEL_TYPE_SEL</code>设置模板组合的类型。详见<a href="../design_and_implementation/kernel_operator_implementation.html">核函数（Kernel）侧算子实现</a>。</td></tr><tr><td>调度模式</td><td>通过<code>__schedmode__(mode)</code>限定符设置核函数调度模式。</td><td>在Host侧Tiling中调用<code>TilingContext::SetScheduleMode</code>设置调度模式。详见<a href="../../../../../api/SIMD-API/basic_api/sync_control/inter_core_sync/SyncAll.html">SyncAll的调度模式约束</a>。</td></tr><tr><td>KFC workspace地址设置</td><td>使用KFC的场景需要预留系统workspace，并通过<code>__kfc_workspace__</code>标记核函数入口的workspace参数，供编译器初始化KFC workspace地址。</td><td>使用KFC的场景需要在Host侧Tiling中预留所需的系统workspace。Kernel侧的KFC workspace地址初始化由框架自动处理，用户按工程规范保留workspace入口参数即可，无需添加<code>__kfc_workspace__</code>标记。详见<a href="../../../appendix/common_operations/how_to_use_workspace.html">如何使用workspace</a>。</td></tr><tr><td>SuperKernel适配</td><td>需要用户提供使用<code>__sk__</code>修饰的SuperKernel入口函数，并通过<code>SK_BIND</code>宏与普通核函数入口绑定，完成SuperKernel适配。</td><td>SuperKernel入口适配由框架内部自动完成，用户无需配置<code>__sk__</code>和<code>SK_BIND</code>。算子仍需满足<a href="../../super_kernel/operator_adaptation.html">算子适配说明</a>中的通用约束。</td></tr></tbody></table></article></div>',1)])])}const s=t(a,[["render",o]]);export{g as __pageData,s as default};
